body.usercss:
	#elrxbmeQPHybmeIizh, #elrxbmerQbBcmetaZG, #elrxbmeotICcmeIYbT {
		display:none;
	}

	.dhxform_obj_material div.dhxform_item_label_top div.dhxform_label{
    	padding-top : 0px;
    }

    .dhxform_obj_material div.dhxform_item_label_top div.dhxform_txt_label2{
