let paramObj = {}
let docObj = {}
let sealObj = new Object();
let sealNamesArr = [];
const rowIdArr = gridObj.getAllRowIds().split(',');

paramObj['SMR_NUMBER'] = formObj.getValue('SMR_NUMBER');
paramObj['DIGITAL_MARK_YN'] = formObj.getValue('ELECTRON_FLAG') ? 'Y' : 'N'; // 전자날인 여부
paramObj['SUBMISSION_PLACE'] = encodeToReturn(formObj.getValue('SUBMISSION_PLACE')); // 제출처
paramObj['SEAL_USE'] = encodeToReturn(formObj.getValue('USE_NUMBER')); // 용도
paramObj['REMARK'] = encodeToReturn(formObj.getValue('EXPLANATION')); // 내용
paramObj['RE_FLAG'] = formObj.getValue('REAL_FLAG') == 1 ? 'R' : 'E'; // 전자실물여부

for (var i in rowIdArr) {
    const rId = rowIdArr[i];
    const smdNumber = gridObj.gridGetCellValueId(rId, 'SMD_NUMBER');
    const subjectEnc = encodeToReturn(gridObj.gridGetCellValueId(rId, 'SUBJECT'));

    const rowManageNumberArr = gridObj.gridGetCellValueId(rId, 'MANAGE_NUMBER').split(',');
    if (rowManageNumberArr.length != 1) {
    	Alert('인감은 하나만 선택하세요');
    	return;
    }
    const rowSealNameArr = gridObj.gridGetCellValueId(rId, 'SEAL_NAME').split(',');
    const rowSealCtgrArr = gridObj.gridGetCellValueId(rId, 'SEAL_CATEGORY').split(',');

    for (var j in rowManageNumberArr) {
        const manageNumber = rowManageNumberArr[j];
        if (sealObj[manageNumber]) continue; // 중복이면 패스
        const sealName = rowSealNameArr[j];
        sealNamesArr.push(sealName);
        const sealCategory = rowSealCtgrArr[j];

        sealObj[manageNumber] = {
            SEAL_NAME: encodeToReturn(sealName),
            SEAL_CATEGORY: sealCategory
        }
    }

    docObj[smdNumber] = {
        TITLE: subjectEnc,
        LINK_CODE: ''
    }
}
paramObj['DOCS_INFO'] = docObj;
paramObj['SEAL_INFO'] = sealObj;
paramObj['SEAL_NAMES'] = encodeToReturn(sealNamesArr.join(',')); // 인감명들 (,로 구분)
const manageNumbers = Object.keys(sealObj).join(',');

doServiceAjax('sepoa.svc.seal.cbo_002.SepoaReqSealServiceCbo', 'CONNECTION', 'getSealManagers', {MANAGE_NUMBERS: manageNumbers}, function(so) {
	if (so.status == 1) {
		paramObj['SEAL_MANAGERS'] = so.result[0];
		window.opener.postMessage(paramObj, '*');
		window.close();
	} else {
		Alert('인감관리자 조회를 실패했습니다');
		return;
	}
});


